USE smart_travel_db;
SET NAMES utf8mb4;
START TRANSACTION;
SET @owner=(SELECT member_id FROM members WHERE login_id='user1' AND status='ACTIVE' AND deleted_at IS NULL);
SET @method=(SELECT id FROM generation_method WHERE code='ai' LIMIT 1);
SET @category=(SELECT MIN(id) FROM category);
SET @course=(SELECT id FROM course WHERE member_no=@owner AND JSON_UNQUOTE(JSON_EXTRACT(condition_meta,'$.fixture'))='MYPAGE-USER1-UPCOMING-202612-1' LIMIT 1);
SET @day=(SELECT id FROM course_day WHERE course_id=@course AND day_no=1);
SET @day=(SELECT id FROM course_day WHERE course_id=@course AND day_no=2);
SET @course=(SELECT id FROM course WHERE member_no=@owner AND JSON_UNQUOTE(JSON_EXTRACT(condition_meta,'$.fixture'))='MYPAGE-USER1-UPCOMING-202612-2' LIMIT 1);
SET @day=(SELECT id FROM course_day WHERE course_id=@course AND day_no=1);
SET @day=(SELECT id FROM course_day WHERE course_id=@course AND day_no=2);
SET @course=(SELECT id FROM course WHERE member_no=@owner AND JSON_UNQUOTE(JSON_EXTRACT(condition_meta,'$.fixture'))='MYPAGE-USER1-UPCOMING-202612-3' LIMIT 1);
SET @day=(SELECT id FROM course_day WHERE course_id=@course AND day_no=1);
SET @day=(SELECT id FROM course_day WHERE course_id=@course AND day_no=2);
COMMIT;
SELECT c.id,c.title,c.start_date,c.end_date,COUNT(DISTINCT d.id) days,COUNT(a.id) places,COUNT(a.place_id) linked_places FROM course c JOIN course_day d ON d.course_id=c.id JOIN activity a ON a.course_day_id=d.id WHERE JSON_UNQUOTE(JSON_EXTRACT(c.condition_meta,'$.fixture')) LIKE 'MYPAGE-USER1-UPCOMING-202612-%' GROUP BY c.id;
